#include "ui_init.h"
#include "ui_util.h"
#include "aic_ui.h"
#include "custom/custom.h"
#include "ui_theme.h"
#include "boot_animation.h"
#include "logic.h"

/* AIC MPP 图片解码器运行时缓存数量上限（定义于 lv_mpp_dec.c，头文件未声明）。
 * 默认 8 张不足：设置弹窗等图数量多的页面切图时 _n/_p 在 LRU 中互相挤出，
 * 每次重新 VE 解码导致延迟。调大到 20 让页面图常驻缓存（退出弹窗时 drop 释放）。 */
extern void lv_img_cache_set_size(uint16_t max_num);

ui_manager_t ui_manager;

/* 动画播到约定帧时预加载主界面：只创建主界面对象并解码图片（不切屏），
 * 用动画剩余帧的播放时间消化主界面加载开销，使动画播完切屏时主界面
 * 已就绪，避免切屏瞬间加载导致的闪烁。 */
void boot_animation_preload_cb(void)
{
    // auto delete screen
    ui_manager_init(&ui_manager, true);

    home_page_create(&ui_manager);

    /* 单位/里程参数恢复定时器同步提前：动画剩余帧时间完成恢复，保留
     * 200ms 轮询 + 完成后自删，确保正确拿到保存的参数 */
    boot_recovery_timer_start();
}

/* 动画播放完毕：切到已就绪的主界面并启动业务逻辑（自检/刷新等） */
void boot_animation_finish_cb(void)
{
    lv_scr_load(home_page_get(&ui_manager)->obj);

    // custom code
    custom_init();
}

void ui_init(void)
{
    aic_font_list_init();

    /* 调大图片缓存数量上限（在创建任何页面图之前，清空无副作用） */
    // lv_img_cache_set_size(30);

    /* 主题 style 就绪 + 按持久化 theme 设定当前主题，供后续 page create 使用 */
    ui_theme_init();

#if defined(AIC_STARTUP_UI_SHOW)
    /* 使用 SDK 默认开机画面：维持原时序 */
    ui_manager_init(&ui_manager, true);

    home_page_create(&ui_manager);
    lv_scr_load(home_page_get(&ui_manager)->obj);
    custom_init();
#else
    /* 自定义开机动画优先：动画期间只加载动画帧，主界面延后到动画播放
     * 完毕，由 boot_animation_finish_cb() 创建，避免主界面图挤占缓存掉帧 */
    boot_animation_init();
#endif
}
